record Cents(int amount) {
    Cents raisedBy(Cents other) { return new Cents(amount + other.amount); }
    Cents scaledBy(int factor) { return new Cents(amount * factor); }
    Cents halved() { return new Cents(amount / 2); }
    Cents cappedAt(Cents ceiling) { return amount > ceiling.amount ? ceiling : this; }
}

record Stay(int enteredAt, int leftAt) {
    static final int MINUTES_PER_HOUR = 60;
    int minutes() { return leftAt - enteredAt; }
    int startedBlocks(int blockMinutes) { return (minutes() + blockMinutes - 1) / blockMinutes; }
    int startedHours() { return startedBlocks(MINUTES_PER_HOUR); }
    Stay shortenedBy(int freeMinutes) { return new Stay(Math.min(enteredAt + freeMinutes, leftAt), leftAt); }
}

