record ChargingSpot(int kilowatts) implements Spot {
    static final int CENTS_PER_KILOWATT = 5;
    public Cents priced(Cents fee, Stay stay) {
        return fee.raisedBy(new Cents(kilowatts * CENTS_PER_KILOWATT).scaledBy(stay.startedHours()));
    }
}
