}
record DayTariff(Cents hourlyRate, Cents dailyCap, int graceMinutes) implements Tariff {
    static final int HOURS_PER_DAY = 24;
    public Cents charge(Stay stay) {
        if (stay.minutes() <= graceMinutes) { return new Cents(0); }
        int hours = stay.startedHours();
        Cents fullDays = dailyCap.scaledBy(hours / HOURS_PER_DAY);
        Cents restOfDay = hourlyRate.scaledBy(hours % HOURS_PER_DAY).cappedAt(dailyCap);
        return fullDays.raisedBy(restOfDay);
    }
}
record NightTariff(Cents flatRate) implements Tariff {
    static final int MINUTES_PER_NIGHT = 720;
    public Cents charge(Stay stay) { return flatRate.scaledBy(stay.startedBlocks(MINUTES_PER_NIGHT)); }
}

record SeasonTicket(String holder, int includedMinutes) {
    Stay billable(Stay stay) { return stay.shortenedBy(includedMinutes); }
}

record Visit(Spot spot, Stay stay) {}

record Cashier(Tariff tariff) {
    Cents dueFor(Spot spot, Stay stay) { return spot.priced(tariff.charge(stay), stay); }
    Cents dueForHolder(Spot spot, Stay stay, SeasonTicket ticket) { return dueFor(spot, ticket.billable(stay)); }
    Cents dayRevenue(List<Visit> visits) {
        return visits.stream().map(visit -> dueFor(visit.spot(), visit.stay())).reduce(new Cents(0), Cents::raisedBy);
    }
}

