    static SpotStatus arrive(SpotStatus status, String plate, int now) {
        return switch (status) {
            case Vacant vacant -> new Taken(plate, now);
            case Held held when held.holder().equals(plate) -> new Taken(plate, now);
            case Held held -> held;
            case Taken taken -> taken;
        };
    }
    static SpotStatus depart(SpotStatus status) { return status.isTaken() ? new Vacant() : status; }
    static Stay stayUntil(Taken taken, int now) { return new Stay(taken.since(), now); }
}

