record Money(int cents) {
    static final int FULL_PERCENT = 100;
    Money plus(Money other) { return new Money(cents + other.cents); }
    Money minus(Money other) { return new Money(cents - other.cents); }
    Money percent(int rate) { return new Money(cents * rate / FULL_PERCENT); }
    Money proRata(int part, int whole) { return new Money(cents * part / whole); }
    Money times(int factor) { return new Money(cents * factor); }
    Money dividedBy(int parts) { return new Money(cents / parts); }
    Money limitedTo(Money ceiling) { return cents > ceiling.cents ? ceiling : this; }
    Money notBelowZero() { return cents < 0 ? new Money(0) : this; }
}

