record HourlyContract(Money hourlyWage, int workedHours) implements Contract {
    static final int REGULAR_HOURS = 160;
    static final int OVERTIME_PERCENT = 125;
    public Money grossPay() {
        int regular = Math.min(workedHours, REGULAR_HOURS);
        int overtime = workedHours - regular;
        return hourlyWage.times(regular).plus(hourlyWage.percent(OVERTIME_PERCENT).times(overtime));
    }
}
record MiniJob(Money agreedPay) implements Contract {
    static final Money EARNINGS_LIMIT = new Money(55600);
    public Money grossPay() { return agreedPay.limitedTo(EARNINGS_LIMIT); }
}

final class TaxTable {
    static final Money BASIC_ALLOWANCE = new Money(100000);
    static final Money BAND_WIDTH = new Money(300000);
    static final int LOWER_RATE = 20;
    static final int UPPER_RATE = 35;
    static Money progressive(Money taxable) {
        Money lower = taxable.limitedTo(BAND_WIDTH);
        return lower.percent(LOWER_RATE).plus(taxable.minus(lower).percent(UPPER_RATE));
    }
    static Money afterAllowance(Money gross, Money allowance) { return progressive(gross.minus(allowance).notBelowZero()); }
}

sealed interface TaxClass permits Single, SingleParent, Married { Money taxOn(Money gross); }
record Single() implements TaxClass { public Money taxOn(Money gross) { return TaxTable.afterAllowance(gross, TaxTable.BASIC_ALLOWANCE); } }
record SingleParent(int children) implements TaxClass {
    static final Money CHILD_ALLOWANCE = new Money(35000);
    public Money taxOn(Money gross) { return TaxTable.afterAllowance(gross, TaxTable.BASIC_ALLOWANCE.plus(CHILD_ALLOWANCE.times(children))); }
}
record Married() implements TaxClass {
    static final int SPOUSES = 2;
    public Money taxOn(Money gross) { return TaxTable.afterAllowance(gross.dividedBy(SPOUSES), TaxTable.BASIC_ALLOWANCE).times(SPOUSES); }
}

