record ChurchTax(int rate) implements Deduction { public Money amountOn(Money gross, Money tax) { return tax.percent(rate); } }
record PensionPlan(Money contribution) implements Deduction { public Money amountOn(Money gross, Money tax) { return contribution.limitedTo(gross); } }

record Employee(String staffId, Contract contract, TaxClass taxClass, List<Deduction> deductions, EmploymentStatus status) {}

record PaySlip(String staffId, Money gross, Money tax, Money deducted, Money net) {}

record PayrollRun(int daysInMonth) {
    static final int ADVANCE_PERCENT = 50;
    Money grossFor(Employee employee) { return employee.status().payable(employee.contract().grossPay(), daysInMonth); }
    PaySlip slipFor(Employee employee) {
        Money gross = grossFor(employee);
        Money tax = employee.taxClass().taxOn(gross);
        Money deducted = employee.deductions().stream().map(deduction -> deduction.amountOn(gross, tax)).reduce(new Money(0), Money::plus);
        return new PaySlip(employee.staffId(), gross, tax, deducted, gross.minus(tax).minus(deducted));
    }
    PaySlip advanceFor(Employee employee) {
        Money gross = grossFor(employee).percent(ADVANCE_PERCENT);
        Money tax = employee.taxClass().taxOn(gross);
        return new PaySlip(employee.staffId(), gross, tax, new Money(0), gross.minus(tax));
    }
    Money totalNet(List<Employee> staff) {
        return staff.stream().map(employee -> slipFor(employee).net()).reduce(new Money(0), Money::plus);
    }
}

final class Personnel {
    static EmploymentStatus grantLeave(EmploymentStatus status, int paidPercent) { return status.isOnPayroll() ? new OnLeave(paidPercent) : status; }
    static EmploymentStatus resume(EmploymentStatus status) { return status instanceof OnLeave ? new Active() : status; }
    static EmploymentStatus terminate(EmploymentStatus status, int lastDay) { return status.isOnPayroll() ? new Terminated(lastDay) : status; }
}

import java.util.List;

record Price(int cents) {
    static final int WHOLE_PERCENT = 100;
    Price plus(Price addend) { return new Price(cents + addend.cents); }
    Price times(int multiple) { return new Price(cents * multiple); }
    Price share(int percent) { return new Price(cents * percent / WHOLE_PERCENT); }
    Price atMost(Price cap) { return cents < cap.cents ? this : cap; }
}

record Period(int pickupDay, int dropoffDay) {
    static final int DAYS_PER_WEEK = 7;
    int days() { return Math.max(dropoffDay - pickupDay, 1); }
    int weeks() { return days() / DAYS_PER_WEEK; }
    int oddDays() { return days() % DAYS_PER_WEEK; }
}

record Mileage(int kmOut, int kmIn) {
    int driven() { return kmIn - kmOut; }
    int over(int allowance) { return Math.max(driven() - allowance, 0); }
}

sealed interface RentalState permits Reserved, OnRoad, Returned, Cancelled {
    default boolean isOpen() { return this instanceof Reserved || this instanceof OnRoad; }
}
record Reserved(String customer, int validUntil) implements RentalState {}
record OnRoad(String customer, int pickedUpOn, int kmAtPickup) implements RentalState {}
record Returned(Period period, Mileage mileage) implements RentalState {}
record Cancelled(int cancelledOn) implements RentalState {}

sealed interface Vehicle permits Compact, Van, Electric {
    Price dailyRate();
    Price kmCharge(Mileage mileage, Period period);
}
record Compact() implements Vehicle {
    static final int BASE_CENTS = 3900, FREE_KM_PER_DAY = 150, CENTS_PER_EXTRA_KM = 25;
    public Price dailyRate() { return new Price(BASE_CENTS); }
    public Price kmCharge(Mileage mileage, Period period) { return new Price(CENTS_PER_EXTRA_KM).times(mileage.over(FREE_KM_PER_DAY * period.days())); }
}
record Van(int payloadKg) implements Vehicle {
    static final int BASE_CENTS = 6900, PAYLOAD_STEP_KG = 500, CENTS_PER_STEP = 1000, FREE_KM_PER_DAY = 100, CENTS_PER_EXTRA_KM = 40;
    int startedSteps() { return (payloadKg + PAYLOAD_STEP_KG - 1) / PAYLOAD_STEP_KG; }
    public Price dailyRate() { return new Price(BASE_CENTS).plus(new Price(CENTS_PER_STEP).times(startedSteps())); }
    public Price kmCharge(Mileage mileage, Period period) { return new Price(CENTS_PER_EXTRA_KM).times(mileage.over(FREE_KM_PER_DAY * period.days())); }
}
record Electric(int batteryKwh) implements Vehicle {
    static final int BASE_CENTS = 5000, RATE_PER_KWH = 20;
    public Price dailyRate() { return new Price(BASE_CENTS + batteryKwh * RATE_PER_KWH); }
    public Price kmCharge(Mileage mileage, Period period) { return new Price(0); }
}

sealed interface Coverage permits LiabilityOnly, PartialCover, FullCover {
    Price premium(Period period);
    Price ownShare(Price damage);
}
record LiabilityOnly() implements Coverage {
    public Price premium(Period period) { return new Price(0); }
    public Price ownShare(Price damage) { return damage; }
}
record PartialCover(Price deductible) implements Coverage {
    static final int CENTS_PER_DAY = 900;
    public Price premium(Period period) { return new Price(CENTS_PER_DAY).times(period.days()); }
    public Price ownShare(Price damage) { return damage.atMost(deductible); }
}
record FullCover() implements Coverage {
    static final int CENTS_PER_DAY = 1800, MAX_BILLED_DAYS = 14;
    public Price premium(Period period) { return new Price(CENTS_PER_DAY).times(Math.min(period.days(), MAX_BILLED_DAYS)); }
    public Price ownShare(Price damage) { return new Price(0); }
}

record Driver(String licence, int age) {
    static final int YOUNG_BELOW = 25, YOUNG_CENTS_PER_DAY = 1200;
    Price surcharge(Period period) { return age < YOUNG_BELOW ? new Price(YOUNG_CENTS_PER_DAY).times(period.days()) : new Price(0); }
}

record Agreement(Vehicle vehicle, Coverage coverage, Period period, Mileage mileage) {}

record Invoicer(int seasonPercent) {
    static final int PAID_DAYS_PER_WEEK = 5;
    Price rent(Vehicle vehicle, Period period) {
        Price rate = vehicle.dailyRate();
        return rate.times(period.weeks() * PAID_DAYS_PER_WEEK).plus(rate.times(period.oddDays())).share(seasonPercent);
    }
    Price total(Agreement agreement) {
        Vehicle vehicle = agreement.vehicle();
        Period period = agreement.period();
        return rent(vehicle, period).plus(vehicle.kmCharge(agreement.mileage(), period)).plus(agreement.coverage().premium(period));
    }
    Price totalWithDriver(Agreement agreement, Driver driver) { return total(agreement).plus(driver.surcharge(agreement.period())); }
    Price afterDamage(Agreement agreement, Price damage) { return total(agreement).plus(agreement.coverage().ownShare(damage)); }
    Price monthRevenue(List<Agreement> agreements) { return agreements.stream().map(this::total).reduce(new Price(0), Price::plus); }
}

final class RentalDesk {
    static RentalState handOver(RentalState state, String customer, int today, int kmNow) {
        return switch (state) {
            case Reserved reserved when today > reserved.validUntil() -> new Cancelled(today);
            case Reserved reserved when reserved.customer().equals(customer) -> new OnRoad(customer, today, kmNow);
            case Reserved reserved -> reserved;
            default -> state;
        };
    }
    static RentalState takeBack(RentalState state, int today, int kmNow) {
        return state instanceof OnRoad onRoad ? new Returned(new Period(onRoad.pickedUpOn(), today), new Mileage(onRoad.kmAtPickup(), kmNow)) : state;
    }
    static RentalState cancel(RentalState state, int today) { return state instanceof Reserved ? new Cancelled(today) : state; }
}

import java.util.List;

record Price(int cents) {
    static final int WHOLE_PERCENT = 100;
    Price plus(Price extra) { return new Price(cents + extra.cents); }
    Price times(int quantity) { return new Price(cents * quantity); }
    Price reducedBy(int percent) { return new Price(cents - cents * percent / WHOLE_PERCENT); }
    Price surchargedBy(int percent) { return new Price(cents + cents * percent / WHOLE_PERCENT); }
    Price roundedUp(int step) { return new Price((cents + step - 1) / step * step); }
    Price atMost(Price cap) { return cents > cap.cents ? cap : this; }
}

record Allotment(int capacity, int sold, int reserved) {
    static final int FULL_HOUSE = 100;
    int free() { return capacity - sold - reserved; }
    int occupancy() { return (sold + reserved) * FULL_HOUSE / capacity; }
    boolean covers(int seats) { return seats <= free(); }
    Allotment withSold(int seats) { return new Allotment(capacity, sold + seats, reserved); }
    Allotment released(int seats) { return new Allotment(capacity, sold, Math.max(reserved - seats, 0)); }
}

sealed interface SaleStatus permits Announced, OnSale, SoldOut, Cancelled {
    default boolean isSelling() { return this instanceof OnSale; }
}
record Announced(int opensOn) implements SaleStatus {}
record OnSale(int openedOn) implements SaleStatus {}
record SoldOut(int closedOn) implements SaleStatus {}
record Cancelled(String reason) implements SaleStatus {}

sealed interface Category permits Standing, Seated, Lounge {
    Price listed(Price base);
}
record Standing() implements Category { public Price listed(Price base) { return base; } }
record Seated(int row) implements Category {
    static final int FRONT_ROWS = 10;
    static final int CENTS_PER_ROW = 120;
    public Price listed(Price base) { return base.plus(new Price(CENTS_PER_ROW).times(Math.max(FRONT_ROWS - row, 0))); }
}
record Lounge(int vouchers) implements Category {
    static final int LOUNGE_PERCENT = 80;
    static final int CENTS_PER_VOUCHER = 450;
    public Price listed(Price base) { return base.surchargedBy(LOUNGE_PERCENT).plus(new Price(CENTS_PER_VOUCHER).times(vouchers)); }
}

sealed interface PriceRule permits EarlyBird, Demand {
    Price adjusted(Price listPrice, Allotment allotment, int daysAhead);
}
record EarlyBird(int minDaysAhead, int discount) implements PriceRule {
    public Price adjusted(Price listPrice, Allotment allotment, int daysAhead) { return daysAhead >= minDaysAhead ? listPrice.reducedBy(discount) : listPrice; }
}
record Demand(int threshold, int stepPercent, Price ceiling) implements PriceRule {
    static final int POINTS_PER_STEP = 10;
    static final int ROUNDING_CENTS = 50;
    public Price adjusted(Price listPrice, Allotment allotment, int daysAhead) {
        int steps = Math.max(allotment.occupancy() - threshold, 0) / POINTS_PER_STEP;
        return listPrice.surchargedBy(steps * stepPercent).roundedUp(ROUNDING_CENTS).atMost(ceiling);
    }
}

record PromoCode(String code, int percent, int minSeats) {
    boolean appliesTo(int seats) { return seats >= minSeats; }
    Price discounted(Price tickets, int seats) { return appliesTo(seats) ? tickets.reducedBy(percent) : tickets; }
}

record Booking(Category category, int seats, int daysAhead) {}

record BoxOffice(Price basePrice, PriceRule rule) {
    static final int FEE_CENTS = 150;
    static final int FEE_CAP_CENTS = 600;
    Price unitPrice(Booking booking, Allotment allotment) {
        return rule.adjusted(booking.category().listed(basePrice), allotment, booking.daysAhead());
    }
    Price serviceFee(int seats) { return new Price(FEE_CENTS).times(seats).atMost(new Price(FEE_CAP_CENTS)); }
    Price orderTotal(Booking booking, Allotment allotment) {
        return unitPrice(booking, allotment).times(booking.seats()).plus(serviceFee(booking.seats()));
    }
    Price promoTotal(Booking booking, Allotment allotment, PromoCode promo) {
        Price tickets = unitPrice(booking, allotment).times(booking.seats());
        return promo.discounted(tickets, booking.seats()).plus(serviceFee(booking.seats()));
    }
    Price nightRevenue(List<Booking> bookings, Allotment allotment) {
        return bookings.stream().map(booking -> orderTotal(booking, allotment)).reduce(new Price(0), Price::plus);
    }
}

final class SaleDesk {
    static SaleStatus opened(SaleStatus status, int today) {
        return switch (status) {
            case Announced announced when announced.opensOn() <= today -> new OnSale(today);
            default -> status;
        };
    }
    static SaleStatus closedIfFull(SaleStatus status, Allotment allotment, int today) { return status.isSelling() && allotment.free() == 0 ? new SoldOut(today) : status; }
    static SaleStatus cancelled(SaleStatus status, String reason) { return status instanceof Cancelled ? status : new Cancelled(reason); }
    static Allotment booked(Allotment allotment, SaleStatus status, int seats) { return status.isSelling() && allotment.covers(seats) ? allotment.withSold(seats) : allotment; }
}

