record BillingPeriod(int startDay, int endDay) {
    int lengthInDays() {
        return endDay - startDay;
    }

    BillingPeriod next() {
        return new BillingPeriod(endDay, endDay + lengthInDays());
    }
}

record Invoice(BillingPeriod billedPeriod, Money amount) {}

enum SubscriptionStatus { ACTIVE, CANCELLED }

class Subscription {
    private final Plan plan;
    private final List<Invoice> invoices = new ArrayList<>();
    private BillingPeriod currentPeriod;
    private SubscriptionStatus status = SubscriptionStatus.ACTIVE;

    Subscription(Plan plan, BillingPeriod firstPeriod) {
        this.plan = plan;
        this.currentPeriod = firstPeriod;
    }

    BillingPeriod currentPeriod() {
        return currentPeriod;
    }

    private boolean isInvoiced(BillingPeriod period) {
        for (Invoice invoice : invoices) {
            if (invoice.billedPeriod().equals(period)) {
                return true;
            }
        }
        return false;
    }

    Invoice issueInvoice() {
        if (status != SubscriptionStatus.ACTIVE) {
            throw new IllegalStateException();
        }
        if (isInvoiced(currentPeriod)) {
            throw new IllegalStateException();
        }
        Money due = plan.priceFor(currentPeriod);
        Invoice invoice = new Invoice(currentPeriod, due);
        invoices.add(invoice);
        return invoice;
    }

    void renew() {
        if (status != SubscriptionStatus.ACTIVE) {
            throw new IllegalStateException();
        }
        currentPeriod = currentPeriod.next();
    }

    void cancel() {
        status = SubscriptionStatus.CANCELLED;
    }

    boolean isActive() {
        return status == SubscriptionStatus.ACTIVE;
    }

    Money totalInvoiced() {
        Money total = new Money(BigDecimal.ZERO);
        for (Invoice invoice : invoices) {
            total = total.plus(invoice.amount());
        }
        return total;
    }
}

import java.math.BigDecimal;

record Money(BigDecimal amount) {
    static final Money ZERO = new Money(BigDecimal.ZERO);

    boolean exceeds(Money other) {
        return amount.compareTo(other.amount) > 0;
    }

    Money minus(Money other) {
        return new Money(amount.subtract(other.amount));
    }
}

record Coverage(Money limit, Money deductible) {
    Money payableFor(Money damage) {
        if (!damage.exceeds(deductible)) {
            return Money.ZERO;
        }
        Money afterDeductible = damage.minus(deductible);
        if (afterDeductible.exceeds(limit)) {
            return limit;
        }
        return afterDeductible;
    }
}

record Policy(String number, Coverage coverage, boolean inForce) {}

record Payout(String policyNumber, Money amount) {}

enum ClaimStatus { OPEN, APPROVED, REJECTED }

class Claim {
    private final Policy policy;
    private final Money damage;
    private ClaimStatus status = ClaimStatus.OPEN;
    private Payout payout;

    Claim(Policy policy, Money damage) {
        this.policy = policy;
        this.damage = damage;
    }

    void approve() {
        if (status != ClaimStatus.OPEN) {
            throw new IllegalStateException();
        }
        if (!policy.inForce()) {
            throw new IllegalStateException();
        }
        Money settlement = policy.coverage().payableFor(damage);
        payout = new Payout(policy.number(), settlement);
        status = ClaimStatus.APPROVED;
    }

    void reject() {
        if (status != ClaimStatus.OPEN) {
            throw new IllegalStateException();
        }
        status = ClaimStatus.REJECTED;
    }

    boolean isApproved() {
        return status == ClaimStatus.APPROVED;
    }

    boolean isRejected() {
        return status == ClaimStatus.REJECTED;
    }

    Money paidAmount() {
        if (payout == null) {
            return Money.ZERO;
        }
        return payout.amount();
    }
}

import java.util.ArrayList;
import java.util.List;

record DueDate(int day) {
    boolean isPassedOn(int today) {
        return today > day;
    }

    int daysLateOn(int today) {
        return Math.max(0, today - day);
    }
}

class BookCopy {
    private final String barcode;
    private boolean onLoan = false;

    BookCopy(String barcode) {
        this.barcode = barcode;
    }

    boolean isOnLoan() {
        return onLoan;
    }

    void checkOut() {
        onLoan = true;
    }

    void checkIn() {
        onLoan = false;
    }
}

class Loan {
    private static final int FEE_PER_DAY = 5;

    private final BookCopy copy;
    private final DueDate dueDate;
    private Integer returnedOn;

    Loan(BookCopy copy, DueDate dueDate) {
        this.copy = copy;
        this.dueDate = dueDate;
    }

    void close(int today) {
        if (returnedOn != null) {
            throw new IllegalStateException();
        }
        returnedOn = today;
        copy.checkIn();
    }

    boolean isOverdueOn(int today) {
        return returnedOn == null && dueDate.isPassedOn(today);
    }

    int lateFeeOn(int today) {
        int lastDay = returnedOn == null ? today : returnedOn;
        return dueDate.daysLateOn(lastDay) * FEE_PER_DAY;
    }
}

class Member {
    private static final int LOAN_DAYS = 14;

    private final String memberId;
    private final int loanLimit;
    private final List<Loan> loans = new ArrayList<>();

    Member(String memberId, int loanLimit) {
        this.memberId = memberId;
        this.loanLimit = loanLimit;
    }

    Loan borrow(BookCopy copy, int today) {
        if (loans.size() >= loanLimit) {
            throw new IllegalStateException();
        }
        if (copy.isOnLoan()) {
            throw new IllegalStateException();
        }
        copy.checkOut();
        DueDate dueDate = new DueDate(today + LOAN_DAYS);
        Loan loan = new Loan(copy, dueDate);
        loans.add(loan);
        return loan;
    }

    void giveBack(Loan loan, int today) {
        loan.close(today);
        loans.remove(loan);
    }

    int openLoans() {
        return loans.size();
    }
}

