record ProductId(String value) {}

record OrderLine(ProductId product, int quantity, Money unitPrice) {
    Money subtotal() {
        return unitPrice.times(quantity);
    }
}

enum OrderStatus { DRAFT, PLACED, CANCELLED }

class Order {
    private final List<OrderLine> lines = new ArrayList<>();
    private OrderStatus status = OrderStatus.DRAFT;

    void addLine(ProductId product, int quantity, Money unitPrice) {
        if (status != OrderStatus.DRAFT) {
            throw new IllegalStateException();
        }
        lines.add(new OrderLine(product, quantity, unitPrice));
    }

    Money total() {
        Money sum = Money.ZERO;
        for (OrderLine line : lines) {
            sum = sum.plus(line.subtotal());
        }
        return sum;
    }

    void place() {
        if (lines.isEmpty()) {
            throw new IllegalStateException();
        }
        status = OrderStatus.PLACED;
    }

    void cancel() {
        status = OrderStatus.CANCELLED;
    }

    boolean isPlaced() {
        return status == OrderStatus.PLACED;
    }
}

import java.util.ArrayList;
import java.util.List;

record TimeSlot(int startHour, int endHour) {
    boolean overlaps(TimeSlot other) {
        return startHour < other.endHour && other.startHour < endHour;
    }
}

record Guest(String guestName, int partySize) {}

enum ReservationStatus { REQUESTED, CONFIRMED, CANCELLED }

class Reservation {
    private final Guest guest;
    private final TimeSlot slot;
    private ReservationStatus status = ReservationStatus.REQUESTED;

    Reservation(Guest guest, TimeSlot slot) {
        this.guest = guest;
        this.slot = slot;
    }

    boolean conflictsWith(TimeSlot requested) {
        return status != ReservationStatus.CANCELLED && slot.overlaps(requested);
